//! The prompts the application itself gives the harness, written in Piton in
//! `system-prompts` and compiled into the application when it is built (see
//! `build.rs`): a module for each prompt, with a constant for each of its
//! pieces of text. A placeholder in a prompt is a name in angle brackets,
//! such as `<codeRoot>`, filled in with [`fill`].

include!(concat!(env!("OUT_DIR"), "/baked_prompts.rs"));

/// `template` with each `<name>` in `values` replaced with its value.
pub fn fill(template: &str, values: &[(&str, &str)]) -> String {
    values
        .iter()
        .fold(template.to_string(), |text, (name, value)| {
            text.replace(&format!("<{name}>"), value)
        })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn placeholders_are_filled() {
        assert_eq!(
            fill("From <a> to <b>, <a>.", &[("a", "here"), ("b", "there")]),
            "From here to there, here."
        );
    }

    /// Each prompt compiled in, with no placeholder left unknown.
    #[test]
    fn prompts_are_baked_in() {
        assert!(divergence::INTRO.contains("<codeRoot>"));
        assert!(divergence::code::TASK.starts_with("Go through every source file"));
        assert_eq!(divergence::spec::ANALYZED, "Spec files to analyze");
        assert!(commit_note::REQUEST.contains("<noNote>"));
        assert!(commit_message::REQUEST.starts_with("Write a git commit message"));
        assert!(file_search::REPLY.contains(r#"{"files": []}"#));
    }
}
//! Commit notes: a one-line summary of each Code, Chain, or Spec task, written
//! by the harness once the task is done, that build up in the git panel above
//! the commit message and go into the next commit. They are saved with the
//! project, in `.suspense/commit-notes.json`, so they survive a restart, and
//! can be edited or removed before committing.

use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{Context as _, Result};
use gpui_kit::{App, Global};
use serde::{Deserialize, Serialize};

use crate::hidden_anchor::APP_DIR;

const FILE: &str = "commit-notes.json";

/// The most of a task's prompt and of its summary handed to the harness, so a
/// note is always quick to write.
const MAX_CHARS: usize = 4_000;

/// What the harness replies when the task changed nothing worth a note.
const NO_NOTE: &str = "NONE";

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct Note {
    pub id: u64,
    pub text: String,
}

/// Bumped whenever the notes change, so whatever shows them reads them again.
#[derive(Default)]
pub struct NotesVersion(pub usize);

impl Global for NotesVersion {}

/// Tells whatever shows the notes that they changed.
pub fn changed(cx: &mut App) {
    let version = cx
        .try_global::<NotesVersion>()
        .map_or(0, |version| version.0);
    cx.set_global(NotesVersion(version + 1));
}

/// The file the project's notes are saved in.
pub fn file(project_dir: &Path) -> PathBuf {
    project_dir.join(APP_DIR).join(FILE)
}

/// The project's notes, oldest first; none if there are none, or they can't be
/// read.
pub fn load(project_dir: &Path) -> Vec<Note> {
    fs::read_to_string(file(project_dir))
        .ok()
        .and_then(|json| serde_json::from_str(&json).ok())
        .unwrap_or_default()
}

/// Saves the project's notes, removing the file once there are none.
pub fn save(project_dir: &Path, notes: &[Note]) -> Result<()> {
    let file = file(project_dir);
    if notes.is_empty() {
        match fs::remove_file(&file) {
            Err(err) if err.kind() != std::io::ErrorKind::NotFound => {
                return Err(err).with_context(|| format!("could not remove {}", file.display()));
            }
            _ => return Ok(()),
        }
    }
    if let Some(dir) = file.parent() {
        fs::create_dir_all(dir).with_context(|| format!("could not create {}", dir.display()))?;
    }
    fs::write(&file, serde_json::to_string_pretty(notes)?)
        .with_context(|| format!("could not save {}", file.display()))
}

/// Adds a note after the others.
pub fn add(project_dir: &Path, text: &str) -> Result<()> {
    let mut notes = load(project_dir);
    let id = notes
        .iter()
        .map(|note| note.id)
        .max()
        .map_or(1, |id| id + 1);
    notes.push(Note {
        id,
        text: text.to_string(),
    });
    save(project_dir, &notes)
}

/// Replaces the text of note `id`.
pub fn edit(project_dir: &Path, id: u64, text: &str) -> Result<()> {
    let mut notes = load(project_dir);
    if let Some(note) = notes.iter_mut().find(|note| note.id == id) {
        note.text = text.to_string();
    }
    save(project_dir, &notes)
}

/// Removes note `id`.
pub fn remove(project_dir: &Path, id: u64) -> Result<()> {
    let mut notes = load(project_dir);
    notes.retain(|note| note.id != id);
    save(project_dir, &notes)
}

/// The commit message: what was typed, then each note that isn't blank as a
/// line of its own, after a blank line when something was typed.
pub fn message(typed: &str, notes: &[Note]) -> String {
    let typed = typed.trim();
    let lines: Vec<String> = notes
        .iter()
        .map(|note| note.text.trim())
        .filter(|text| !text.is_empty())
        .map(|text| format!("- {text}"))
        .collect();
    match (typed.is_empty(), lines.is_empty()) {
        (_, true) => typed.to_string(),
        (true, false) => lines.join("\n"),
        (false, false) => format!("{typed}\n\n{}", lines.join("\n")),
    }
}

/// Writes a task's note, `None` if it changed nothing: from what was asked
/// and the harness's summary of what it did, quickly, with a small model, at
/// low effort, and no tools.
pub fn summarize(project_dir: &Path, prompt: &str, result: &str) -> Result<Option<String>> {
    let cut = |text: &str| text.chars().take(MAX_CHARS).collect::<String>();
    // Written in system-prompts/commit-note.pi.
    use crate::baked_prompts::{commit_note, fill};
    let request = format!(
        "{}\n\n{}:\n{}\n\n{}:\n{}",
        fill(commit_note::REQUEST, &[("noNote", NO_NOTE)]),
        commit_note::TASK,
        cut(prompt),
        commit_note::RESULT,
        cut(result)
    );
    let reply = crate::harness::ask_quickly(project_dir, &request)?;
    Ok(clean(&reply))
}

/// The note in the harness's reply: its first line with anything around it
/// trimmed, or `None` for no note.
fn clean(reply: &str) -> Option<String> {
    let line = reply.lines().map(str::trim).find(|line| !line.is_empty())?;
    let line = line
        .trim_start_matches(['-', '*', ' '])
        .trim_matches(['"', '\'', '`'])
        .trim_end_matches('.')
        .trim();
    (!line.is_empty() && line != NO_NOTE).then(|| line.to_string())
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    use super::{Note, add, clean, edit, load, message, remove, save};

    /// Notes are added in order, edited, and removed, and saved with the
    /// project as they change; none left removes the file.
    #[test]
    fn notes_are_saved_with_the_project() {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("target/commit-notes-test");
        std::fs::remove_dir_all(&dir).ok();
        assert!(load(&dir).is_empty());

        add(&dir, "Add the ribbon").unwrap();
        add(&dir, "Fix scrolling").unwrap();
        let notes = load(&dir);
        assert_eq!(
            notes
                .iter()
                .map(|note| note.text.as_str())
                .collect::<Vec<_>>(),
            ["Add the ribbon", "Fix scrolling"]
        );
        edit(&dir, notes[1].id, "Fix tree scrolling").unwrap();
        remove(&dir, notes[0].id).unwrap();
        assert_eq!(
            load(&dir),
            [Note {
                id: notes[1].id,
                text: "Fix tree scrolling".into()
            }]
        );
        save(&dir, &[]).unwrap();
        assert!(!dir.join(".suspense/commit-notes.json").exists());
    }

    /// The typed message comes first, then the notes as lines of their own;
    /// blank notes are left out.
    #[test]
    fn notes_go_into_the_commit_message() {
        let notes = [
            Note {
                id: 1,
                text: "Add the ribbon".into(),
        });
        let height = self.rows.total_height().min(MAX_PROMPT_HEIGHT);
        let prompt = div()
            .id(("compiled-prompt", task_ix))
            .min_w_0()
            .h(height)
            .child(self.rows.element(render));
        // Lets UI tests find the compiled prompt; inert in normal builds.
        gpui_kit::TestSupportExt::test_support(prompt).into_any_element()
    }
}

/// Writes a commit note for a task from its prompt and its final summary.
type Summarize = fn(&Path, &str, &str) -> Result<Option<String>>;

/// Has `summarize` write the note of a task that asked `asked` and finished
/// with `result`, in the background, and adds it to the project's commit
/// notes. A task that changed nothing gets none, and one that couldn't be
/// written is left out: the note is only a convenience.
fn add_commit_note(
    summarize: Summarize,
    project_dir: PathBuf,
    asked: String,
    result: String,
    cx: &mut App,
) {
    let note = cx.background_spawn({
        let project_dir = project_dir.clone();
        async move { summarize(&project_dir, &asked, &result) }
    });
    cx.spawn(async move |cx| {
        if let Ok(Some(note)) = note.await
            && commit_notes::add(&project_dir, &note).is_ok()
        {
            cx.update(commit_notes::changed);
        }
    })
    .detach();
}

/// A question asked from the Ask tab.
struct Ask {
    id: usize,
    task: PromptTask,
    /// Set when it is stopped, so its record says it was cancelled.
    stopped: Arc<AtomicBool>,
    /// Its run, stopped when the question is stopped.
    _run: Task<()>,
}

/// A question's run as far as it went, saved beside the question in
/// `.suspense/asks` when dropped: once the run is over, or when the question
/// is stopped.
struct AskLog {
    file: Option<PathBuf>,
    record: RunRecord,
    stopped: Arc<AtomicBool>,
}

impl Drop for AskLog {
    fn drop(&mut self) {
        let Some(file) = self.file.take() else {
            return;
        };
        let mut record = std::mem::take(&mut self.record);
        record.cancelled |= self.stopped.load(Ordering::SeqCst);
        // Off the UI thread: a long run's output can be large.
        std::thread::spawn(move || prompt_history::save_record(&file, &record).ok());
    }
}

